<?php
require_once 'conexion.php';$id=(int)($_GET['id']??0);$m=['id_medicamento'=>0,'id_categoria'=>'','nombre'=>'','presentacion'=>'','concentracion'=>'','precio_venta'=>'0.00','requiere_receta'=>0,'condicion_almacenamiento'=>'','codigo_barras'=>'','precio_costo'=>'0.00','iva_porcentaje'=>'0.00'];
