 value="<?=h($m['precio_costo'])?>"></div><div class="column"><label class="label">IVA (%) *</label><input class="input" type="number" name="iva_porcentaje" min="0" max="100" step="0.01" required value="<?=h($m['iva_porcentaje'])?>"></div></div><div class="field"><label class="label">Código de barras</label><input class="input" name="codigo_barras" maxlength="50" value="<?=h($m['codigo_barras'])?>"></div><div class="field"><label class="label">Condición de almacenamiento</label><input class="input" name="condicion_almacenamiento" maxlength="100" value="<?=h($m['condicion_almacenamiento'])?>" placeholder="Ej. Mantener en lugar fresco y seco"></div><label class="checkbox"><input type="checkbox" name="requiere_receta" value="1" <?=$m['requiere_receta']?'checked':''?>> Requiere receta médica</label></section><footer class="modal-card-foot"><button type="submit" class="button is-primary">Guardar medicamento</button><button type="button" class="button" onclick="document.getElementById('modal-contenido').innerHTML=''">Cancelar</button></footer></form></div></div>
